import { createHash } from 'node:crypto';

export const MAX_DEPTH = 64;
export const MAX_CANON_BYTES = 262_144;
export class DefectError extends Error { constructor(readonly defect: Defect) { super(defect); } }
export type Defect = 'external_ref' | 'too_deep' | 'oversize' | 'uncanonicalizable';

/** Deterministic JSON. Keys sorted by UTF-16 code unit; string VALUES NFC-normalised;
 *  keys left RAW (a homoglyph property name must be a change, not a fold);
 *  array order significant; numbers/booleans/null left to JSON.stringify. */
export function canonical(v: unknown, depth = 0): string {
  if (depth > MAX_DEPTH) throw new DefectError('too_deep');
  return JSON.stringify(norm(v, depth));
}
function norm(v: unknown, depth: number): unknown {
  if (depth > MAX_DEPTH) throw new DefectError('too_deep');
  if (typeof v === 'string') return v.normalize('NFC');   // NOT NFKC: it folds ligatures
  if (Array.isArray(v)) return v.map((x) => norm(x, depth + 1));
  if (v && typeof v === 'object') {
    const out: Record<string, unknown> = {};
    for (const k of Object.keys(v as object).sort())      // default sort = UTF-16 code unit
      out[k] = norm((v as Record<string, unknown>)[k], depth + 1);
    return out;
  }
  return v;
}

const sha = (s: string) => createHash('sha256').update(s, 'utf8').digest('hex');

export type CatalogDef =
  | { kind: 'tool';     def: { name: string; title?: string; description?: string;
                              inputSchema: unknown; outputSchema?: unknown; annotations?: unknown } }
  | { kind: 'prompt';   def: { name: string; title?: string; description?: string; arguments?: unknown } }
  | { kind: 'resource'; def: { uri?: string; uriTemplate?: string; name: string; title?: string;
                              description?: string; mimeType?: string; annotations?: unknown } };

/** defHash covers everything the model will see. schemaHash excludes prose, so the
 *  review UI can label a change 'description only' vs 'schema' without re-diffing. */
export function defHashes(it: CatalogDef): { defHash: string; schemaHash: string } {
  const d = it.def as Record<string, unknown>;
  const prose = { name: d.name ?? null, title: d.title ?? null, description: d.description ?? null };
  const shape =
    it.kind === 'tool'   ? { inputSchema: d.inputSchema ?? null, outputSchema: d.outputSchema ?? null,
                             annotations: d.annotations ?? null }
  : it.kind === 'prompt' ? { arguments: d.arguments ?? null }
  :                        { uri: d.uri ?? null, uriTemplate: d.uriTemplate ?? null,
                             mimeType: d.mimeType ?? null, annotations: d.annotations ?? null };
  const cProse = canonical(prose), cShape = canonical(shape);
  if (cProse.length + cShape.length > MAX_CANON_BYTES) throw new DefectError('oversize');
  // � domain separator: a prompt named X can never collide with a tool named X
  return { defHash: sha(`${it.kind}�${cProse}�${cShape}`),
           schemaHash: sha(`${it.kind}�${cShape}`) };
}

/** A $ref that is not a local pointer is a hash-invisible mutation channel. */
export function externalRefs(s: unknown, out: string[] = [], at = '#', depth = 0): string[] {
  if (depth > MAX_DEPTH) throw new DefectError('too_deep');
  if (Array.isArray(s)) s.forEach((v, i) => externalRefs(v, out, `${at}/${i}`, depth + 1));
  else if (s && typeof s === 'object')
    for (const [k, v] of Object.entries(s)) {
      if (k === '$ref' && !(typeof v === 'string' && v.startsWith('#'))) out.push(at);
      else externalRefs(v, out, `${at}/${k}`, depth + 1);
    }
  return out;
}

export const itemKind    = pgEnum('item_kind',    ['tool', 'prompt', 'resource']);
export const defectKind  = pgEnum('defect_kind',  ['external_ref', 'too_deep', 'oversize', 'uncanonicalizable']);

export const toolEmbedding = pgTable('tool_embedding', {
  // ---- settled columns: serverId, kind, itemName, description, inputSchema,
  //      tokenCost, tsv, embedding, generation ----
  defHash:    char('def_hash',    { length: 64 }).notNull(),
  schemaHash: char('schema_hash', { length: 64 }).notNull(),
  defect:     defectKind('defect'),                 // null = clean
  defSeenAt:  timestamp('def_seen_at', { withTimezone: true }).notNull().defaultNow(),
}, (t) => [
  primaryKey({ columns: [t.serverId, t.kind, t.itemName] }),
  index('tool_embedding_changed_idx').on(t.serverId, t.kind).where(sql`${t.defect} is not null`),
]);

export const reviewState = pgEnum('review_state', ['unreviewed', 'approved', 'rejected']);

export const serverItemOverride = pgTable('server_item_override', {
  serverId: uuid('server_id').notNull().references(() => servers.id, { onDelete: 'cascade' }),
  kind:     itemKind('kind').notNull(),
  itemName: text('item_name').notNull(),            // BARE upstream name (settled)
  // ---- settled columns ----
  enabled:     boolean('enabled').notNull().default(true),
  description: text('description'),                 // operator override — NEVER hashed, it is ours
  // ---- guardrail ----
  reviewState:  reviewState('review_state').notNull().default('unreviewed'),
  approvedHash: char('approved_hash', { length: 64 }),
  approvedBy:   text('approved_by'),                // denormalised display name, no FK (audit rule)
  approvedAt:   timestamp('approved_at', { withTimezone: true }),
}, (t) => [
  primaryKey({ columns: [t.serverId, t.kind, t.itemName] }),
  // THE ENTIRE STATE MACHINE. There is no transition code.
  check('approved_iff_hash',
        sql`(${t.reviewState} = 'approved') = (${t.approvedHash} IS NOT NULL)`),
]);

// servers gains ONE column, shared by both halves of the subsystem:
export const serverTrust = pgEnum('server_trust', ['reviewed', 'trusted']);
