export type IntegrityMode = 'enforce' | 'observe' | 'off';

export type Item = {
  kind: ItemKind; bare: string; namespaced: string;   // `${slug}__${bare}`, built at cache time
  def: unknown; defHash: string; schemaHash: string; defect: Defect | null;
  enabled: boolean; review: 'unreviewed' | 'approved' | 'rejected'; approvedHash: string | null;
};

/** 'off' turns off REVIEW, never VALIDATION: a defective item is unexposable in every mode. */
export function integrityOk(i: Item, mode: IntegrityMode): boolean {
  if (i.defect) return false;
  if (mode === 'off') return true;
  if (i.review === 'approved' && i.approvedHash === i.defHash) return true;
  return mode === 'observe';          // observe: expose, but still event + audit + badge
}

export function isExposed(scope: ResolvedScope, server: string, kind: ItemKind, bare: string): boolean {
  const s = this.servers.get(server);
  if (!s || !scope.serverIds.has(s.id) || s.state === 'disabled') return false;
  if (!scope.selects(server, kind, bare)) return false;              // group item selection
  const i = s.items.get(`${kind}�${bare}`);
  return !!i && i.enabled && i.review !== 'rejected' && integrityOk(i, this.integrityMode);
}

// Replace the cache PER (server, kind), and ONLY for a kind whose list call SUCCEEDED.
// Otherwise an induced partial failure launders a change: prompts/list fails -> we think the
// prompt was deleted -> next success re-adds it as 'unreviewed'... or, worse under
// newItemsOnEnabledServer='approve', re-adds it APPROVED with a new hash.
for (const kind of ['tool', 'prompt', 'resource'] as const) {
  const res = await listSafely(client, kind, signal);
  if (!res.ok) { log.warn({ server, kind, err: res.err }, 'kind list failed; keeping prior cache'); continue; }
  if (gen !== this.generation || client !== s.client) return;   // settled superseded-state guard
  await upsertKind(server, kind, res.items);                    // hash computed inside
}

// stale:true has NO interaction: a dropped transport re-discovers nothing, so no hash moves.
// On RECONNECT the cache is rewritten, but the upsert is `WHERE def_hash IS DISTINCT FROM $new`,
// so a flapping server produces no churn, no events and no spurious quarantines.

export type Effect = 'allow' | 'deny' | 'require_approval';
export type DenyReason =
  | { k: 'selector' }
  | { k: 'args'; ptr: string; op: ArgConstraint['op'] };   // NEVER the value: args are not logged

export type PolicyInput = {
  principal: Principal;          // EXPLICIT parameter — never read from the ALS store
  serverSlug: string;
  kind: 'tool' | 'prompt' | 'resource';
  bareName: string;
  args: unknown;                 // raw tool arguments, unmodified
};

export type PolicyDecision =
  | { effect: 'allow'; ruleId: string | null }                                 // null = default allow
  | { effect: 'deny' | 'require_approval'; ruleId: string; seq: number;
      note: string | null; reason: DenyReason };

export type Explain = PolicyDecision & {
  considered: Array<{ id: string; seq: number; matched: boolean;
                      skip?: 'disabled'|'subject'|'server'|'kind'|'name' }>;
};

/** FIRST MATCH on the pre-ordered array. Implicit final allow: grants already default-deny. */
export function evaluate(rules: readonly CompiledRule[], i: PolicyInput, trace: false): PolicyDecision;
export function evaluate(rules: readonly CompiledRule[], i: PolicyInput, trace: true): Explain;
export function evaluate(rules: readonly CompiledRule[], i: PolicyInput, trace = false) {
  const considered: Explain['considered'] = [];
  for (const r of rules) {
    const skip = selectorSkip(r, i);
    if (trace) considered.push({ id: r.id, seq: r.seq, matched: !skip, skip });
    if (skip) continue;
    const fail = argsOk(r.args, i.args);                 // null = all constraints passed
    const effect = fail ? r.elseEffect : r.effect;
    const base = effect === 'allow'
      ? { effect, ruleId: r.id } as const
      : { effect, ruleId: r.id, seq: r.seq, note: r.note,
          reason: fail ? { k: 'args', ...fail } as const : { k: 'selector' } as const };
    return trace ? { ...base, considered } : base;
  }
  const base = { effect: 'allow', ruleId: null } as const;
  return trace ? { ...base, considered } : base;
}

function selectorSkip(r: CompiledRule, i: PolicyInput) {
  if (!r.enabled) return 'disabled' as const;
  if (!subjectMatches(r, i.principal)) return 'subject' as const;
  if (r.serverSlug !== null && r.serverSlug !== i.serverSlug) return 'server' as const;
  if (r.itemKind !== 'any' && r.itemKind !== i.kind) return 'kind' as const;
  if (!globMatch(r.namePattern, i.bareName)) return 'name' as const;
  return null;
}

/** A machine principal matches a 'role' rule ONLY via its owning user's role.
 *  admin:false is a literal type on the machine arm (settled) and is never widened here. */
function subjectMatches(r: CompiledRule, p: Principal): boolean {
  switch (r.subjectKind) {
    case 'any':     return true;
    case 'role':    return p.role === r.subjectId;
    case 'user':    return p.userId === r.subjectId;
    case 'api_key': return p.kind === 'machine' && p.apiKeyId === r.subjectId;
  }
}

import { posix } from 'node:path';

function argsOk(cs: readonly ArgConstraint[], args: unknown) {
  for (const c of cs) {
    const v = ptrGet(args, c.ptr);
    let ok: boolean;
    switch (c.op) {
      case 'present': ok = v !== undefined; break;
      case 'absent':  ok = v === undefined; break;
      case 'maxLen':  ok = typeof v === 'string' ? v.length <= c.n
                         : Array.isArray(v)      ? v.length <= c.n : false; break;
      default:
        // FAIL-CLOSED: missing path or non-string (e.g. {"path":["/tmp","/etc"]}) fails.
        if (typeof v !== 'string') { ok = false; break; }
        ok = c.op === 'equals' ? v === c.value
           : c.op === 'oneOf'  ? c.values.includes(v)
           : c.op === 'prefix' ? v.startsWith(c.value)
           :                     pathUnder(v, c.value);
    }
    if (!ok) return { ptr: c.ptr, op: c.op };
  }
  return null;
}

/** ponytail: LEXICAL containment. A symlink under root defeats it; resolving is the
 *  upstream server's job, not the gateway's. Relative paths are unverifiable -> deny. */
function pathUnder(v: string, root: string): boolean {
  if (v.includes('\0') || v.includes('\\')) return false;
  if (!posix.isAbsolute(v)) return false;
  const p = posix.normalize(v);
  const r = posix.normalize(root).replace(/\/+$/, '');
  return p === r || p.startsWith(r + '/');
}

/** RFC 6901. Object.hasOwn blocks walking into __proto__ / constructor / prototype. */
function ptrGet(root: unknown, ptr: string): unknown {
  if (ptr === '') return root;
  let cur: unknown = root;
  for (const raw of ptr.slice(1).split('/')) {
    if (cur === null || typeof cur !== 'object') return undefined;
    const k = raw.replaceAll('~1', '/').replaceAll('~0', '~');
    if (Array.isArray(cur)) {
      const n = Number(k);
      if (!Number.isInteger(n) || n < 0) return undefined;
      cur = cur[n];
    } else {
      if (!Object.hasOwn(cur, k)) return undefined;
      cur = (cur as Record<string, unknown>)[k];
    }
  }
  return cur;
}

/** literal text + '*' only. Linear, no backtracking, structurally ReDoS-free. */
function globMatch(pat: string, s: string): boolean {
  if (pat === '*') return true;
  const parts = pat.split('*');
  if (parts.length === 1) return pat === s;
  const first = parts[0], last = parts[parts.length - 1];
  if (!s.startsWith(first) || !s.endsWith(last)) return false;
  let i = first.length;
  for (const p of parts.slice(1, -1)) {
    const j = s.indexOf(p, i);
    if (j < 0) return false;
    i = j + p.length;
  }
  return i <= s.length - last.length;
}

// packages/core/src/policy.ts — core owns the TYPE and the ERROR, never the decision or the data.
export type PolicyGate = (i: PolicyInput) => PolicyDecision;
export class PolicyBlockedError extends Error {
  constructor(readonly decision: Extract<PolicyDecision, { effect: 'deny' | 'require_approval' }>) {
    super('Blocked by policy');
  }
}
export const ALLOW_ALL: PolicyGate = () => ({ effect: 'allow', ruleId: null });

// packages/core/src/engine.ts
const RESOLVED = Symbol('resolved');
export type ResolvedTool = { server: string; bare: string; client: Client; [RESOLVED]: true };

export class Engine {
  constructor(private readonly o: {
    transports: TransportFactory;
    policy?: PolicyGate;          // default ALLOW_ALL — tests and embedded use need no policy store
    integrity?: IntegrityMode;    // default 'enforce'
  }) {}

  /** ONE construction site for `Tool not found: ${name}`. */
  resolveTool(scope: ResolvedScope, name: string): ResolvedTool { /* ... */ }

  async callTool(scope: ResolvedScope, principal: Principal,
                 name: string, args: unknown, signal: AbortSignal) {
    const t = this.resolveTool(scope, name);                       // may throw ToolUnavailableError
    const d = (this.o.policy ?? ALLOW_ALL)({
      principal, serverSlug: t.server, kind: 'tool', bareName: t.bare, args,
    });
    if (d.effect !== 'allow') throw new PolicyBlockedError(d);
    return this.dispatch(t, args, signal);                         // private; accepts only ResolvedTool
  }

  private dispatch(t: ResolvedTool, args: unknown, signal: AbortSignal) { /* ... */ }
}

// packages/server/src/policy/gate.ts — the implementation, with the snapshot.
let snapshot: { rules: CompiledRule[]; loadedAt: number; ok: boolean } | null = null;
export const gate: PolicyGate = (i) => {
  if (!snapshot) throw new PolicyStoreUnavailable();   // boot-time only; MCP routes 503 before this
  return evaluate(snapshot.rules, i, false);
};
export async function reload(db: Db) { /* SELECT ... WHERE enabled ORDER BY seq, id; replace on success only */ }

/** Flatten a schema to sorted `<json-pointer>\t<scalar>` lines. A key REORDER produces zero
 *  changed lines; an added `"format":"uri"` produces exactly one. No JSON-tree diff widget. */
export function flatten(v: unknown, at = '', out: string[] = []): string[] {
  if (v !== null && typeof v === 'object') {
    const ks = Array.isArray(v) ? v.map((_, i) => String(i)) : Object.keys(v).sort();
    for (const k of ks) flatten((v as any)[k], `${at}/${k.replaceAll('~','~0').replaceAll('/','~1')}`, out);
  } else out.push(`${at}\t${JSON.stringify(v)}`);
  return out.sort();
}

export type DiffView = {
  changed: ('description' | 'schema')[];   // derived from defHash vs schemaHash — no classifier
  tokenCostDelta: number;                  // token_cost already on the row
  prose:  { a: string; b: string };        // LINE diff, whitespace MADE VISIBLE
  schema: { a: string[]; b: string[] };    // LINE diff over flatten() output
};

// Renderer rules (non-negotiable, the review pane is a trust boundary for the OPERATOR'S EYES):
//  - never render description as markdown or HTML; it is <pre>, escaped
//  - trailing spaces -> '·', newlines -> '⏎', tabs -> '→'
//  - Unicode bidi controls (U+202A..U+202E, U+2066..U+2069) rendered as <U+202E>, NEVER applied
//  - zero-width (U+200B..U+200D, U+FEFF) rendered as <U+200B>
//  - a line longer than 2000 chars is clamped with an explicit '… +N chars' affordance

guardrails: z.object({
  integrity: z.enum(['enforce', 'observe', 'off']).default('enforce')
    .describe('Hide items whose definition changed since approval. `observe` still records and alerts but keeps them exposed. Structural defects (external $ref, oversize, too deep) are hidden in every mode.'),
  newItemsOnEnabledServer: z.enum(['quarantine', 'approve']).default('quarantine')
    .describe('What happens to a tool a server adds AFTER it was enabled. Items present when the server was first enabled are approved by the operator who enabled it.'),
}).default({})
